# Runtime v2 · B7 Composition, Layout, Drawing: ba phase và đọc state theo phase
# Nguồn: "Jetpack Compose phases" (developer.android.com, đọc 2026-11-23): ba phase, thuật toán layout một lượt, state đọc theo phase,
# tối ưu bằng Modifier.offset { }, vòng lặp onSizeChanged. Sim mới runtime.scroll; sim cũ runtime.phases giữ làm tab thứ hai; giữ mục cầu nối X1.

SEC_ORDER = {'b7': ['hook', 'three', 'layout', 'reads', 'optimize', 'loop', 'x1', 'bugs', 'exercises', 'recall']}


def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.scroll ----------------
    m = lambda k, vi, en=None: a('m.scroll.' + k, vi, en)
    m('title', 'Đọc vị trí cuộn ở đâu: composition, layout hay draw?', 'Where to read the scroll position: composition, layout or draw?')
    m('overview', 'Người dùng cuộn danh sách qua 3 frame; `firstVisibleItemScrollOffset` đổi mỗi frame. Chọn nơi đọc giá trị đó: trong composition (`Modifier.offset(dp)`), trong bước placement của layout (`Modifier.offset { }`), hay trong draw (`drawBehind`). Lựa chọn thứ tư là ví dụ vòng lặp `onSizeChanged` của tài liệu. Đếm số lần mỗi phase chạy.', 'The user scrolls the list for 3 frames; `firstVisibleItemScrollOffset` changes every frame. Choose where that value is read: in composition (`Modifier.offset(dp)`), in layout\'s placement step (`Modifier.offset { }`), or in draw (`drawBehind`). The fourth option is the docs\' `onSizeChanged` loop example. Count how many times each phase runs.')
    m('wrapup', 'Compose theo dõi lần đọc state THEO PHASE. Đọc ở composition thì mỗi lần đổi phải chạy cả ba phase; đọc ở placement thì chỉ layout và draw; đọc ở draw thì chỉ draw. Với giá trị đổi mỗi frame như vị trí cuộn hay animation, hoãn lần đọc tới phase muộn nhất có thể tiết kiệm phần lớn công việc. Còn ghi state trong layout để composition đọc thì tạo vòng lặp qua nhiều frame.', 'Compose tracks state reads PER PHASE. Reading in composition means every change runs all three phases; reading in placement, only layout and draw; reading in draw, only draw. For values that change every frame, such as scroll position or animations, deferring the read to the latest possible phase saves most of the work. And writing state during layout for composition to read creates a loop across frames.')
    m('simp.1', 'Số lần chạy được đếm theo phase cho cả màn hình, không theo từng node; giả định mỗi frame cuộn đổi giá trị đúng một lần.', 'Runs are counted per phase for the whole screen, not per node; it assumes each scroll frame changes the value exactly once.')
    m('simp.2', 'Giá trị (40, 80, 120 px; ảnh cao 200 px) là minh họa. Tài liệu nói đọc trong layout chỉ làm draw chạy lại nếu kích thước hoặc vị trí đổi; ở đây vị trí luôn đổi.', 'Values (40, 80, 120 px; a 200 px image) are illustrative. The docs say a read in layout re-runs draw only if size or position changed; here position always changes.')
    m('ctl.hint', 'Chạy lần lượt ba nơi đọc và so ba bộ đếm; rồi xem vòng lặp onSizeChanged.', 'Run the three read locations in turn and compare the three counters; then look at the onSizeChanged loop.')
    m('ctl.where', 'Đọc giá trị ở', 'Read the value in')
    for k, vi, en in [('comp', 'Trong composition: Modifier.offset(dp)', 'Composition: Modifier.offset(dp)'), ('layout', 'Placement của layout: Modifier.offset { }', 'Layout placement: Modifier.offset { }'),
                      ('draw', 'Trong draw: drawBehind { }', 'Draw: drawBehind { }'), ('loop', 'Vòng lặp: onSizeChanged ghi state', 'Loop: onSizeChanged writes state')]:
        m('ctl.where.' + k, vi, en)
    m('diagramTitle', 'State và ba phase của một frame', 'State and the three phases of a frame')
    m('diagramDesc', 'State được đọc ở một trong ba phase; phase đó chạy lại và kéo theo các phase sau nó', 'State is read in one of the three phases; that phase re-runs and pulls along the phases after it')
    for k, vi, en in [('state', 'firstVisibleItemScrollOffset', 'firstVisibleItemScrollOffset'), ('comp', 'Composition (cái gì)', 'Composition (what)'), ('layout', 'Layout: đo và đặt (ở đâu)', 'Layout: measure and place (where)'), ('draw', 'Draw (vẽ thế nào)', 'Draw (how)')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('comp', 'Lần composition', 'Compositions'), ('layout', 'Lần layout', 'Layouts'), ('draw', 'Lần draw', 'Draws'), ('frames', 'Frame', 'Frames')]:
        m('met.' + k, vi, en)
    m('st.value', 'Giá trị (px)', 'Value (px)')
    m('st.ran', 'Phase chạy trong frame', 'Phases run in the frame')
    S = [
        ('intro.comp', 'Đọc vị trí cuộn trong composition', 'Reading the scroll position in composition', 'Giá trị được đọc ngay trong thân `Box` để tính `dp` truyền cho `Modifier.offset(…)`. Compose ghi nhận: scope composition của `Box` phụ thuộc vào state này.', 'The value is read right in the `Box` body to compute the `dp` passed to `Modifier.offset(…)`. Compose records that the `Box` composition scope depends on this state.'),
        ('intro.layout', 'Đọc vị trí cuộn trong placement', 'Reading the scroll position in placement', 'Lambda của `Modifier.offset { }` chỉ chạy ở bước placement của layout. Lần đọc xảy ra ở đó, nên composition không phụ thuộc vào state này.', 'The `Modifier.offset { }` lambda only runs in layout\'s placement step. The read happens there, so composition does not depend on this state.'),
        ('intro.draw', 'Đọc vị trí cuộn trong draw', 'Reading the scroll position in draw', 'Khối `drawBehind { }` chạy ở phase draw. Lần đọc ở đó chỉ ràng buộc phase draw.', 'The `drawBehind { }` block runs in the draw phase. A read there only binds the draw phase.'),
        ('frame1.comp', 'Frame {f}: chạy cả composition → layout → draw', 'Frame {f}: composition → layout → draw', 'Giá trị đổi nên scope composition chạy lại: nội dung của `Box` được tính lại, rồi đo và đặt lại, rồi vẽ lại. Mọi thứ đều chạy dù chỉ VỊ TRÍ của ảnh đổi.', 'The value changed, so the composition scope re-runs: the `Box` content is recomputed, then re-measured and re-placed, then redrawn. Everything runs even though only the image\'s POSITION changed.'),
        ('frame.comp', 'Frame {f}: lại cả ba phase', 'Frame {f}: all three phases again', 'Lặp lại mỗi frame trong suốt lúc cuộn.', 'Repeated every frame for the whole scroll.'),
        ('frame1.layout', 'Frame {f}: layout → draw (không composition)', 'Frame {f}: layout → draw (no composition)', 'Chỉ bước placement chạy lại để tính offset mới, rồi draw vì vị trí đổi. Composition không bị đụng tới.', 'Only the placement step re-runs to compute the new offset, then draw because the position changed. Composition is untouched.'),
        ('frame.layout', 'Frame {f}: chỉ layout → draw', 'Frame {f}: layout → draw', 'Như frame trước.', 'Same as the previous frame.'),
        ('frame1.draw', 'Frame {f}: chỉ draw', 'Frame {f}: draw only', 'Chỉ khối vẽ chạy lại với độ rộng mới của thanh tiến độ.', 'Only the drawing block re-runs with the progress bar\'s new width.'),
        ('frame.draw', 'Frame {f}: chỉ draw', 'Frame {f}: draw only', 'Như frame trước.', 'Same as the previous frame.'),
        ('end.comp', 'Kết thúc: 3 composition, 3 layout, 3 draw', 'The end: 3 compositions, 3 layouts, 3 draws', 'Mỗi sự kiện cuộn làm cả nội dung được tính lại, đo, đặt và vẽ. Tài liệu gọi đây là cách làm chạy được nhưng không tối ưu.', 'Every scroll event recomputes, measures, places and draws the whole content. The docs call this working but suboptimal.'),
        ('end.layout', 'Kết thúc: 0 composition, 3 layout, 3 draw', 'The end: 0 compositions, 3 layouts, 3 draws', 'Đổi sang lambda là đủ để bỏ hết composition trong lúc cuộn.', 'Switching to the lambda is enough to drop every composition while scrolling.'),
        ('end.draw', 'Kết thúc: chỉ 3 draw', 'The end: only 3 draws', 'Khi giá trị chỉ ảnh hưởng tới cách vẽ (màu, một thanh vẽ tay), đọc trong draw là rẻ nhất.', 'When a value only affects how something is drawn (a colour, a hand-drawn bar), reading it in draw is cheapest.'),
        ('intro.loop', 'Ảnh trên, chữ dưới, nối bằng onSizeChanged', 'Image on top, text below, glued with onSizeChanged', 'Ví dụ của tài liệu: lấy chiều cao ảnh bằng `onSizeChanged` (chạy trong layout), ghi vào state, rồi `Text` đọc state đó trong composition để đặt padding.', 'The docs\' example: get the image height with `onSizeChanged` (run during layout), write it into state, then `Text` reads that state in composition to set its padding.'),
        ('l1comp', 'Frame 1, lúc composition: padding = 0', 'Frame 1, composition: padding = 0', '`imageHeightPx` còn bằng 0, nên `Text` nhận `padding(top = 0)`.', '`imageHeightPx` is still 0, so `Text` gets `padding(top = 0)`.'),
        ('l1layout', 'Frame 1, layout: onSizeChanged ghi 200', 'Frame 1, layout: onSizeChanged writes 200', 'Đo xong ảnh, callback ghi chiều cao thật vào state. Composition của frame này đã xong, nên Compose lên lịch recompose cho frame SAU. Các phase không quay ngược trong cùng một frame.', 'With the image measured, the callback writes the real height into state. This frame\'s composition is already done, so Compose schedules a recomposition for the NEXT frame. Phases do not go backwards within one frame.'),
        ('l1draw', 'Frame 1, draw: chữ đè lên ảnh', 'Frame 1, draw: the text overlaps the image', 'Frame này được vẽ với padding 0: người dùng thấy một frame chữ nằm chồng lên ảnh.', 'This frame is drawn with padding 0: the user sees one frame of text on top of the image.'),
        ('l2', 'Frame 2: composition → layout → draw với padding 200', 'Frame 2: composition → layout → draw with padding 200', 'Giờ `Text` có đúng padding. Layout ghi lại cùng giá trị nên không lên lịch thêm recompose.', 'Now `Text` has the right padding. Layout writes the same value again, so no further recomposition is scheduled.'),
        ('end.loop', 'Kết thúc: 2 frame cho một bố cục', 'The end: 2 frames for one layout', 'Kết quả đúng nhưng tốn một frame thừa và UI nhảy trên màn hình.', 'The result is right, but it costs an extra frame and the UI jumps on screen.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('end.comp', 'Đọc trong composition không phải là sai: đó là nền tảng của recomposition. Nó chỉ thừa khi giá trị đổi mỗi frame mà nội dung không đổi. [[src:cp-phases]]', 'Reading in composition is not wrong: it is the basis of recomposition. It is only wasteful when the value changes every frame while the content does not. [[src:cp-phases]]'),
        ('end.layout', 'Tài liệu: lambda có chi phí riêng, nhưng lợi ích của việc giới hạn lần đọc vào layout lớn hơn khi giá trị đổi mỗi frame. [[src:cp-phases]]', 'The docs: the lambda has its own cost, but limiting the read to layout outweighs it when the value changes every frame. [[src:cp-phases]]'),
        ('end.draw', 'Ví dụ trong tài liệu: đọc `color` trong `Canvas` thì đổi màu chỉ chạy lại phase draw. [[src:cp-phases]]', 'The docs\' example: reading `color` in a `Canvas` means a colour change re-runs only the draw phase. [[src:cp-phases]]'),
        ('overlap', 'Tài liệu cảnh báo mẫu chung: `onSizeChanged()`, `onGloballyPositioned()` hay thao tác layout khác ghi state mà composition đọc. [[src:cp-phases]]', 'The docs warn about the general pattern: `onSizeChanged()`, `onGloballyPositioned()` or other layout operations writing state that composition reads. [[src:cp-phases]]'),
        ('end.loop', 'Cách sửa: dùng layout có sẵn cho việc xếp chồng (`Column`), hoặc layout tùy chỉnh đo ảnh rồi đặt chữ trong cùng một lượt layout.', 'The fix: use a built-in layout for stacking (`Column`), or a custom layout that measures the image and places the text in the same layout pass.')]:
        m('co.' + k, vi, en)
    a('cap.scroll', 'State (trái) có thể được đọc ở một trong ba phase. Mũi tên từ state cho biết phase đọc nó; phase đó chạy lại và kéo theo các phase sau (composition → layout → draw). Mũi tên ngược từ layout về state là lần ghi trong onSizeChanged.', 'State (left) can be read in one of the three phases. The arrow from the state shows which phase reads it; that phase re-runs and pulls along the later ones (composition → layout → draw). The backward arrow from layout to state is the write in onSizeChanged.')

    # ---------------- chương B7 ----------------
    C = 'b7'
    a(C + '.sim.runtime.scroll', 'Đọc ở phase nào', 'Which phase reads')
    a(C + '.sim.runtime.phases', 'Ba phase của một node', 'The three phases of one node')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Một ảnh nền dịch theo vị trí cuộn (hiệu ứng parallax). Viết `Modifier.offset(y = (scroll / 2).toDp())` hay `Modifier.offset { IntOffset(0, scroll / 2) }` thì khác gì nhau, khi người dùng cuộn liên tục 60 frame mỗi giây?', 'A background image shifts with the scroll position (a parallax effect). What difference does `Modifier.offset(y = (scroll / 2).toDp())` versus `Modifier.offset { IntOffset(0, scroll / 2) }` make while the user scrolls continuously at 60 frames per second?')
    B(C, S, 1, 'ans', 'Cách đầu đọc `scroll` trong composition: mỗi frame cuộn, nội dung được recompose, đo, đặt và vẽ lại. Cách sau đọc trong lambda chạy ở bước placement: mỗi frame chỉ layout và draw chạy, không có recomposition nào. Đó chính là ví dụ tối ưu trong tài liệu phases.', 'The first reads `scroll` in composition: every scroll frame recomposes, measures, places and draws the content. The second reads it in a lambda run during placement: each frame only layout and draw run, with no recomposition at all. That is exactly the optimisation example in the phases docs.')

    S = 'three'
    a(C + '.sec.%s.title' % S, 'Ba phase của một frame', 'The three phases of a frame')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Hệ View có ba phase chính: measure, layout, drawing. Compose giống vậy nhưng thêm một phase quan trọng ở đầu: composition. Composition quyết định HIỂN THỊ GÌ (chạy composable, tạo mô tả UI); Layout quyết định ĐẶT Ở ĐÂU (đo và đặt, gồm hai bước measurement và placement); Drawing quyết định VẼ THẾ NÀO (mỗi phần tử vẽ vào Canvas). Thứ tự thường giữ nguyên, dữ liệu đi một chiều composition → layout → drawing. Ngoại lệ đáng chú ý: `BoxWithConstraints`, `LazyColumn`, `LazyRow`, nơi composition của con phụ thuộc vào phase layout của cha. [[src:cp-phases]]', 'The View system has three main phases: measure, layout, drawing. Compose is similar but adds an important phase at the start: composition. Composition decides WHAT to show (running composables, creating a UI description); Layout decides WHERE to place it (measuring and placing, in two steps, measurement and placement); Drawing decides HOW it renders (each element draws into a Canvas). The order is generally fixed, with data flowing one way: composition → layout → drawing. Notable exceptions: `BoxWithConstraints`, `LazyColumn` and `LazyRow`, where the composition of children depends on the parent\'s layout phase. [[src:cp-phases]]')
    B(C, S, 2, 'p', 'Về khái niệm, mỗi frame đều có ba phase; thực tế Compose tránh lặp lại việc cho cùng kết quả với cùng đầu vào: bỏ qua composable có thể dùng lại kết quả cũ (chương B2), và Compose UI không đo hay vẽ lại cả cây khi không cần. Điều đó làm được vì Compose theo dõi lần đọc state trong TỪNG phase. Chương B5 cho thấy cả ba phase nằm trong frame mà Recomposer xin: recompose và apply trước, rồi Compose UI đo, đặt và vẽ. [[src:cp-phases]]', 'Conceptually every frame has all three phases; in practice Compose avoids repeating work with the same inputs and results: it skips composables that can reuse their former result (chapter B2), and Compose UI does not re-measure or redraw the whole tree when it does not need to. That works because Compose tracks state reads within EACH phase. Chapter B5 showed all three phases happen inside the frame the Recomposer requests: recompose and apply first, then Compose UI measures, places and draws. [[src:cp-phases]]')

    S = 'layout'
    a(C + '.sec.%s.title' % S, 'Layout: một lượt đi qua cây', 'Layout: a single pass through the tree')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Phase layout duyệt cây theo thuật toán ba bước cho mỗi node: đo con (nếu có); dựa vào kích thước con, tự quyết kích thước của mình; đặt các con theo vị trí tương đối với mình. Cuối phase, mỗi node có chiều rộng, chiều cao và tọa độ x, y để vẽ. Với ví dụ `Row(Image, Column(Text, Text))`: Row đo Image; đo Column, Column đo hai Text, lấy chiều rộng lớn nhất và tổng chiều cao, đặt hai Text chồng dọc; rồi Row lấy chiều cao lớn nhất và tổng chiều rộng, đặt hai con. [[src:cp-phases]]', 'The layout phase traverses the tree with a three-step algorithm per node: measure the children (if any); based on those measurements, decide its own size; place the children relative to its own position. At the end of the phase, each node has a width, a height and x, y coordinates to draw at. With `Row(Image, Column(Text, Text))`: the Row measures the Image; measures the Column, which measures its two Texts, takes the maximum width and the sum of heights, and stacks them vertically; then the Row takes the maximum height and the sum of widths and places its two children. [[src:cp-phases]]')
    B(C, S, 2, 'p', 'Mỗi node chỉ được thăm MỘT lần, nên thời gian duyệt tăng tuyến tính theo số node. Nếu mỗi node bị thăm nhiều lần, thời gian tăng nhanh hơn nhiều khi cây lớn lên. Phase draw rồi duyệt cây lần nữa từ trên xuống, mỗi node tự vẽ: Row vẽ nền, Image vẽ, Column vẽ, hai Text vẽ. [[src:cp-phases]]', 'Each node is visited only ONCE, so traversal time grows linearly with the number of nodes. If nodes were visited many times, time would grow much faster as the tree gets larger. The draw phase then traverses the tree again top to bottom, each node drawing itself: the Row draws its background, the Image draws, the Column draws, the two Texts draw. [[src:cp-phases]]')

    S = 'reads'
    a(C + '.sec.%s.title' % S, 'Đọc state theo phase', 'Phased state reads')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Khi một snapshot state được đọc trong một phase, Compose tự ghi nhận nó đang làm gì lúc đó (read observer, chương B4), để chạy lại đúng phần đã đọc khi giá trị đổi. Mỗi khối mã chạy lại được khi state đã đọc đổi là một restart scope. Nơi tạo và lưu state hầu như không quan trọng; quan trọng là giá trị được ĐỌC ở đâu và khi nào. [[src:cp-phases]]', 'When snapshot state is read during a phase, Compose automatically records what it was doing (the read observer, chapter B4), so it can re-run exactly the reader when the value changes. Each block of code that can re-run when a read state changes is a restart scope. Where state is created and stored barely matters; what matters is where and when its value is READ. [[src:cp-phases]]')
    B(C, S, 2, 'p', 'Đọc trong composable hoặc lambda `@Composable`: ảnh hưởng composition và có thể cả các phase sau; Recomposer lên lịch chạy lại các composable đã đọc (có thể skip nếu đầu vào không đổi). Đọc trong layout: bước measurement (lambda đo của `Layout`, `LayoutModifier.measure`) hoặc placement (khối placement, lambda của `Modifier.offset { }`); đổi giá trị thì Compose UI lên lịch layout, và draw nếu kích thước hoặc vị trí đổi. Measurement và placement có restart scope riêng. Đọc trong draw (`Canvas`, `drawBehind`, `drawWithContent`): chỉ phase draw chạy lại. [[src:cp-phases]]', 'Reading in a composable or `@Composable` lambda: affects composition and possibly later phases; the Recomposer schedules reruns of the composables that read it (they may be skipped if inputs did not change). Reading in layout: in the measurement step (a `Layout`\'s measure lambda, `LayoutModifier.measure`) or the placement step (the placement block, the `Modifier.offset { }` lambda); a change makes Compose UI schedule layout, and draw if size or position changed. Measurement and placement have separate restart scopes. Reading in draw (`Canvas`, `drawBehind`, `drawWithContent`): only the draw phase re-runs. [[src:cp-phases]]')
    B(C, S, 3, 'kt', 'var offsetX by remember { mutableStateOf(8.dp) }\nText("Hello", modifier = Modifier.offset {\n    IntOffset(offsetX.roundToPx(), 0)      // đọc ở PLACEMENT: đổi offsetX → layout chạy lại\n})\n\nvar color by remember { mutableStateOf(Color.Red) }\nCanvas(modifier) {\n    drawRect(color)                        // đọc ở DRAW: đổi color → chỉ draw chạy lại\n}', 'var offsetX by remember { mutableStateOf(8.dp) }\nText("Hello", modifier = Modifier.offset {\n    IntOffset(offsetX.roundToPx(), 0)      // read in PLACEMENT: a new offsetX re-runs layout\n})\n\nvar color by remember { mutableStateOf(Color.Red) }\nCanvas(modifier) {\n    drawRect(color)                        // read in DRAW: a new color re-runs draw only\n}')

    S = 'optimize'
    a(C + '.sec.%s.title' % S, 'Hoãn lần đọc tới phase muộn nhất', 'Defer the read to the latest phase')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Ví dụ của tài liệu: ảnh dịch theo `listState.firstVisibleItemScrollOffset` bằng `Modifier.offset(dp)`. Mã chạy được nhưng mỗi sự kiện cuộn làm cả nội dung `Box` được tính lại, đo, đặt và vẽ, dù chỉ vị trí đổi. Đổi sang `Modifier.offset { IntOffset(0, offset / 2) }`: lambda chạy ở bước placement, lần đọc rời khỏi composition, và khi cuộn chỉ layout và draw chạy lại. Lambda có chi phí riêng, nhưng với giá trị đổi mỗi frame thì đáng. [[src:cp-phases]]', 'The docs\' example: an image shifted by `listState.firstVisibleItemScrollOffset` through `Modifier.offset(dp)`. It works, but every scroll event recomputes, measures, places and draws the whole `Box` content, though only the position changed. Switch to `Modifier.offset { IntOffset(0, offset / 2) }`: the lambda runs in the placement step, the read leaves composition, and scrolling re-runs only layout and draw. The lambda has its own cost, but for a value that changes every frame it is worth it. [[src:cp-phases]]')
    B(C, S, 2, 'p', 'Khi buộc phải đọc trong composition, vẫn có thể giảm số lần recompose bằng cách lọc thay đổi với `derivedStateOf` (chương B4), ví dụ chỉ quan tâm "đã cuộn qua phần tử đầu chưa" thay vì vị trí chính xác. [[src:cp-phases]] [[src:and-effects]]', 'When the read must happen in composition, you can still reduce recompositions by filtering changes with `derivedStateOf` (chapter B4), for example caring only whether the list has scrolled past the first item rather than the exact position. [[src:cp-phases]] [[src:and-effects]]')
    B(C, S, 3, 'predict', 'Trong mô phỏng ngay dưới, qua 3 frame cuộn, đọc ở composition, ở placement và ở draw lần lượt cho bao nhiêu lần composition, layout, draw?', 'In the simulation just below, over 3 scroll frames, how many compositions, layouts and draws do reading in composition, in placement and in draw give?')
    B(C, S, 3, 'ans', 'Đọc ở composition: 3 / 3 / 3. Ở placement: 0 / 3 / 3. Ở draw: 0 / 0 / 3 (theo thứ tự composition / layout / draw).', 'Composition: 3 / 3 / 3. Placement: 0 / 3 / 3. Draw: 0 / 0 / 3.')

    S = 'loop'
    a(C + '.sec.%s.title' % S, 'Vòng lặp giữa các phase qua nhiều frame', 'Loops between phases across frames')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Trong một frame, các phase luôn theo cùng thứ tự và không quay ngược. Nhưng app vẫn có thể tạo vòng lặp QUA NHIỀU frame. Ví dụ của tài liệu: `Modifier.onSizeChanged` (chạy trong layout) ghi chiều cao ảnh vào state, và `Text` đọc state đó trong composition để đặt padding. Frame đầu, padding còn 0 và chữ được vẽ đè lên ảnh; layout ghi giá trị mới nên frame sau recompose, lần này mới đúng. Việc phải đổi Px về Dp một cách gượng ép đã là dấu hiệu có vấn đề. [[src:cp-phases]]', 'Within a frame, phases always run in the same order and never go back. But an app can still create a loop ACROSS frames. The docs\' example: `Modifier.onSizeChanged` (run during layout) writes the image height into state, and `Text` reads that state in composition to set its padding. In the first frame the padding is still 0 and the text is drawn over the image; layout wrote a new value, so the next frame recomposes, and only then is it right. The awkward conversion from Px back to Dp is already a sign of trouble. [[src:cp-phases]]')
    B(C, S, 2, 'p', 'Cảnh giác với mẫu chung: `onSizeChanged()`, `onGloballyPositioned()` hay thao tác layout khác ghi state mà composition đọc. Cách đúng là để layout giải quyết bố cục trong một lượt: dùng layout có sẵn (`Column` cho xếp chồng dọc), hoặc viết layout tùy chỉnh đo ảnh rồi đặt chữ ngay trong cùng một lượt. [[src:cp-phases]]', 'Beware of the general pattern: `onSizeChanged()`, `onGloballyPositioned()` or other layout operations writing state that composition reads. The right approach is to let layout solve the arrangement in one pass: use a built-in layout (`Column` for vertical stacking), or write a custom layout that measures the image and places the text in the same pass. [[src:cp-phases]]')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Header thu gọn theo cuộn bị giật; Layout Inspector cho thấy cả màn hình recompose mỗi frame cuộn.', 'A collapsing header stutters while scrolling; Layout Inspector shows the whole screen recomposing every scroll frame.')
    B(C, S, 1, 'cause', 'Chiều cao header được tính từ `scrollState.value` ngay trong thân composable cha và truyền vào `Modifier.height(dp)`.', 'The header height is computed from `scrollState.value` right in the parent composable body and passed to `Modifier.height(dp)`.')
    B(C, S, 1, 'fix', 'Hoãn lần đọc: dịch header bằng `Modifier.offset { }` hoặc `graphicsLayer { translationY = … }`; nếu thật sự phải đổi kích thước, dùng `Modifier.layout { }` để đọc giá trị trong lambda đo/đặt thay vì trong composition.', 'Defer the read: shift the header with `Modifier.offset { }` or `graphicsLayer { translationY = … }`; if the size must truly change, use `Modifier.layout { }` so the value is read in the measure/place lambda instead of composition.')
    B(C, S, 2, 'bug', 'Một hộp thoại nháy: frame đầu nút "OK" nằm đè lên nội dung, frame sau mới về đúng chỗ.', 'A dialog flickers: in the first frame the "OK" button overlaps the content, and only in the next frame does it move into place.')
    B(C, S, 2, 'cause', 'Chiều cao nội dung được lấy bằng `onGloballyPositioned`, ghi vào state, rồi dùng làm padding của nút trong composition: vòng lặp qua hai frame.', 'The content height is obtained with `onGloballyPositioned`, written into state, then used as the button\'s padding in composition: a two-frame loop.')
    B(C, S, 2, 'fix', 'Đặt nội dung và nút trong một `Column` (hoặc layout tùy chỉnh) để kích thước được giải quyết trong một lượt layout.', 'Put the content and the button in a `Column` (or a custom layout) so sizes are resolved in a single layout pass.')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Một nút có màu nền animate liên tục bằng `animateColorAsState`. Viết lại để mỗi frame chỉ phase draw chạy lại:', 'A button\'s background colour animates continuously with `animateColorAsState`. Rewrite it so each frame only the draw phase re-runs:')
    B(C, S, 1, 'exkt', 'val color by animateColorAsState(if (active) Teal else Gray)\nBox(Modifier.size(48.dp).background(color))   // đọc color trong composition', 'val color by animateColorAsState(if (active) Teal else Gray)\nBox(Modifier.size(48.dp).background(color))   // reads color in composition')
    B(C, S, 1, 'solkt', 'val color by animateColorAsState(if (active) Teal else Gray)\nBox(Modifier.size(48.dp).drawBehind {\n    drawRect(color)                               // đọc color trong draw\n})', 'val color by animateColorAsState(if (active) Teal else Gray)\nBox(Modifier.size(48.dp).drawBehind {\n    drawRect(color)                               // reads color in draw\n})')
    B(C, S, 1, 'sol', '`background(color)` nhận giá trị nên `color` bị đọc ngay trong composition. `drawBehind { }` là lambda chạy ở draw, nên mỗi frame animation chỉ vẽ lại.', '`background(color)` takes a value, so `color` is read right in composition. `drawBehind { }` is a lambda run during draw, so each animation frame only redraws.')
    B(C, S, 2, 'ex', 'Phân loại nơi đọc: (a) `Text(name)`; (b) `Modifier.offset { IntOffset(x, 0) }`; (c) `Canvas { drawCircle(c) }`; (d) lambda đo của `Layout(measurePolicy = …)` đọc `itemCount`.', 'Classify the read location: (a) `Text(name)`; (b) `Modifier.offset { IntOffset(x, 0) }`; (c) `Canvas { drawCircle(c) }`; (d) a `Layout(measurePolicy = …)` measure lambda reading `itemCount`.')
    B(C, S, 2, 'sol', '(a) composition; (b) layout, bước placement; (c) draw; (d) layout, bước measurement (đổi giá trị làm đo lại, rồi đặt và vẽ nếu kích thước/vị trí đổi).', '(a) composition; (b) layout, placement step; (c) draw; (d) layout, measurement step (a change re-measures, then places and draws if size/position change).')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Ba phase và câu hỏi mỗi phase trả lời?', 'The three phases and the question each answers?')
    B(C, S, 1, 'ans', 'Composition: hiển thị gì. Layout: đặt ở đâu (đo rồi đặt). Drawing: vẽ thế nào.', 'Composition: what to show. Layout: where to place it (measure, then place). Drawing: how it renders.')
    B(C, S, 2, 'ask', 'Đổi một state đọc trong `drawBehind` làm phase nào chạy lại?', 'Changing a state read in `drawBehind` re-runs which phase?')
    B(C, S, 2, 'ans', 'Chỉ draw.', 'Only draw.')
    B(C, S, 3, 'ask', 'Vì sao ghi state trong `onSizeChanged` để composition đọc là mẫu xấu?', 'Why is writing state in `onSizeChanged` for composition to read a bad pattern?')
    B(C, S, 3, 'ans', 'Phase không quay ngược trong cùng frame, nên kết quả chỉ đúng ở frame sau: tốn một frame thừa và có một frame vẽ sai.', 'Phases do not go back within a frame, so the result is only right in the next frame: an extra frame and one wrongly drawn frame.')
    for q, qv, qe, av, ae, wv, we in [
        ('q3', 'Phase layout thăm mỗi node bao nhiêu lần?', 'How many times does the layout phase visit each node?',
         'Một lần.', 'Once.', 'Đo con, tự quyết kích thước, đặt con trong một lượt; thời gian tăng tuyến tính theo số node.', 'Measure children, decide own size, place children in one pass; time grows linearly with node count.'),
        ('q4', 'Lambda của `Modifier.offset { }` chạy ở phase nào?', 'In which phase does the `Modifier.offset { }` lambda run?',
         'Layout, bước placement.', 'Layout, the placement step.', 'Vì vậy đọc state trong đó không gây recomposition.', 'So reading state inside it causes no recomposition.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)


def override(o):
    C = 'b7'
    o(C + '.title', 'Composition, Layout, Drawing: ba phase và đọc state theo phase', 'Composition, Layout, Drawing: the three phases and phased state reads')
    o(C + '.essence',
      'Một frame của Compose đi qua ba phase theo thứ tự: Composition (hiển thị gì), Layout (đo và đặt ở đâu, một lượt qua cây), Drawing (vẽ thế nào). Về khái niệm mọi frame có cả ba, nhưng Compose bỏ qua việc không cần làm lại, nhờ theo dõi lần đọc state trong TỪNG phase.\n'
      'Đọc state trong composable thì đổi giá trị chạy lại composition (và các phase sau); đọc trong lambda đo/đặt (như `Modifier.offset { }`) thì chỉ layout và draw; đọc trong `drawBehind`, `Canvas` thì chỉ draw. Với giá trị đổi mỗi frame (cuộn, animation), hoãn lần đọc tới phase muộn nhất. Ghi state trong layout để composition đọc tạo vòng lặp qua nhiều frame.\n'
      'Nguồn chính: trang "Jetpack Compose phases" của tài liệu Android.',
      'A Compose frame goes through three phases in order: Composition (what to show), Layout (measure and place, in one pass through the tree), Drawing (how it renders). Conceptually every frame has all three, but Compose skips work it does not need to redo, by tracking state reads within EACH phase.\n'
      'Reading state in a composable means a change re-runs composition (and later phases); reading in a measure/place lambda (such as `Modifier.offset { }`) means only layout and draw; reading in `drawBehind` or `Canvas` means only draw. For values that change every frame (scrolling, animation), defer the read to the latest phase. Writing state in layout for composition to read creates a loop across frames.\n'
      'Main source: the "Jetpack Compose phases" page of the Android docs.')
    o(C + '.goal.g1', 'Đã thấy frame cuộn đầu tiên và các phase chạy', 'Saw the first scroll frame and the phases that ran')
    o(C + '.goal.g2', 'Đã chạy một nơi đọc tới cuối', 'Ran one read location to the end')
